function summarizeWindow(events, nowMs, windowMs, cap) {
  const seenIds = new Set();
  const deduped = [];
  for (const ev of events) {
    if (ev && typeof ev.id === 'string' && ev.id !== '') {
      if (seenIds.has(ev.id)) continue;
      seenIds.add(ev.id);
    }
    deduped.push(ev);
  }

  const qualifying = deduped.filter(
    (ev) =>
      ev &&
      typeof ev.ts === 'number' &&
      Number.isFinite(ev.ts) &&
      ev.ts >= nowMs - windowMs &&
      ev.ts <= nowMs &&
      ev.provider === 'opencode-go' &&
      !ev.error &&
      typeof ev.model === 'string' &&
      !/-free$/i.test(ev.model)
  );

  const used = qualifying.length;
  const minTs = used > 0 ? Math.min(...qualifying.map((ev) => ev.ts)) : 0;

  const counts = {};
  for (const ev of qualifying) {
    const key = ev.model.toLowerCase().replace(/^opencode-go\//, '');
    counts[key] = (counts[key] || 0) + 1;
  }
  const byModel = {};
  for (const key of Object.keys(counts).sort()) {
    byModel[key] = counts[key];
  }

  return {
    used,
    remaining: Math.max(0, cap - used),
    pct: Math.round((used / cap) * 1000) / 10,
    overCap: used > cap,
    oldestExpiresAt: used === 0 ? null : minTs + windowMs,
    byModel,
  };
}
